"""Build a class-independent Windows 11 screenshot skills mission."""
from pathlib import Path
import html
import json

ROOT = Path(__file__).resolve().parent.parent
TITLE = 'Екранна снимка (Screenshot) в Windows 11 — заснемане и записване'
CSS = '''body{font:19px/1.65 Arial,sans-serif;color:#20354c;background:white;margin:0;padding:24px;max-width:920px;box-sizing:border-box}p{margin:16px 0}h3{font-size:23px;color:#146681;margin:23px 0 10px}strong{color:#155e75}li{margin:10px 0}kbd{display:inline-block;font:700 18px/1.3 Arial,sans-serif;background:white;border:1px solid #b8cddd;border-bottom:3px solid #8ba9bd;border-radius:7px;padding:7px 11px;margin:3px;color:#123c58}figure{margin:20px 0;padding:18px;background:#f1f7fb;border:1px solid #d9e7f1;border-radius:15px;text-align:center}img{display:block;max-width:100%;height:auto;margin:auto}figcaption{font-size:14px;color:#52687d;line-height:1.45;margin-top:10px}.keys{text-align:center;background:#edf5fd;border-radius:14px;padding:20px;margin:18px 0}.key{background:#e8f6ed;border-left:5px solid #399c72;padding:15px 19px;border-radius:8px;margin:18px 0}.example{background:#fff5df;border-left:5px solid #e4aa3b;padding:15px 19px;border-radius:8px;margin:18px 0}.path{background:#edf2f8;padding:13px 16px;border-radius:9px;overflow-wrap:anywhere}.flow{display:flex;flex-wrap:wrap;gap:9px;align-items:center;justify-content:center;background:#edf5fd;padding:18px;border-radius:12px}.flow span{background:white;border:1px solid #c6dbe8;padding:10px;border-radius:9px}.screen{width:88%;max-width:500px;margin:15px auto;border:9px solid #25455d;border-bottom-width:20px;border-radius:12px;background:#e6f1ff;padding:20px;box-sizing:border-box;text-align:left}.selection{padding:16px;border:3px dashed #2088c8;background:white;border-radius:5px}.label{font-size:14px;color:#52687d}.file{font-size:23px;font-weight:bold;color:#125e7a}.calculator{font-size:32px;text-align:right;color:#143f5a;background:#f6f8fb;padding:10px;border-radius:7px}a{color:#126797;overflow-wrap:anywhere}@media(max-width:550px){body{padding:14px}kbd{font-size:16px;padding:6px 8px}.screen{width:100%;padding:12px}.file{font-size:19px}}'''


def wrap(body):
    return '<!doctype html><html lang="bg"><head><meta charset="utf-8"><style>' + CSS + '</style></head><body>' + body + '</body></html>'


def keys(*names):
    return '<div class="keys">' + ' + '.join('<kbd>' + html.escape(n) + '</kbd>' for n in names) + '</div>'


def flow(*labels):
    return '<div class="flow">' + ' → '.join('<span>' + html.escape(v) + '</span>' for v in labels) + '</div>'


def info(sid, title, body):
    return {'id': sid, 'step_content': {'type': 'information', 'title': title, 'instruction': wrap(body), 'instruction_format': 'html'}, 'step_rules': {}}


def submission(sid, title, filename, folder, requirement):
    body = '<p>Предай <strong>' + requirement + '</strong>.</p>'
    body += '<div class="path">' + folder + ' → <strong>' + filename + '</strong></div>'
    body += '<p>Името е пример: вместо <strong>Martin</strong> използвай своето име.</p>'
    body += '''<ol><li>Натисни <strong>„Избери файл…“</strong> под указанията.</li><li>Отвори посочената папка, избери своята снимка и натисни <strong>Отвори (Open)</strong>.</li><li>Виж дали се показва името на избрания файл.</li><li>Натисни <strong>„Напред“</strong>, за да предадеш този резултат и да продължиш.</li></ol><p>Прикачи изображение във формат <strong>PNG</strong> или <strong>JPG/JPEG</strong>, до <strong>20 MB</strong>.</p>'''
    return {'id': sid, 'step_content': {'type': 'file', 'title': title, 'instruction': wrap(body), 'instruction_format': 'html'}, 'step_rules': {'send_progress': True}}


steps = [
    info('intro', 'За какво е този урок', '''<p><strong>Екранна снимка</strong> — на английски <strong>Screenshot</strong> — е изображение на това, което виждаш на екрана.</p><div class="screen"><div class="label">Първо заснемаме целия екран</div><div class="selection">След това избираме само една област.</div></div><p>В Windows 11 ще направиш две упражнения:</p><ol><li><strong>Снимка на целия екран</strong> — записваш я с описателно име и предаваш файла.</li><li><strong>Снимка на част от екрана</strong> — записваш я като отделен файл и предаваш и него.</li></ol>''' + flow('Цял екран', 'Запис', 'Предаване') + flow('Избрана част', 'Запис', 'Предаване') + '''<p>Накрая ще разбереш как настройката в Windows 11 променя действието на самостоятелния клавиш <strong>Prt Scr</strong>. В указанията ще намираш както клавишна комбинация, така и начин с мишката през менюта и бутони.</p>'''),
    info('prepare', 'Подготви нещо за снимане', '''<ol><li>Отвори <strong>Старт (Start)</strong>, напиши <strong>Калкулатор</strong> или <strong>Calculator</strong> и избери приложението.</li><li>Натисни последователно цифрите <strong>1, 2, 3, 4, 5</strong>. На дисплея ще се появи <strong>12 345</strong> или <strong>12,345</strong> според настройките.</li><li>Остави прозореца на калкулатора видим.</li></ol><div class="screen"><div class="label">Пример за съдържание, което ще заснемем</div><div class="calculator">12 345</div></div><p>В първото упражнение снимката ще включва <strong>целия екран с прозореца на калкулатора</strong>. Във второто ще избереш <strong>само областта около калкулатора</strong>.</p>'''),
    info('capture-full', 'Снимай целия екран', keys('Windows', 'Print Screen') + '''<h3>С клавишна комбинация</h3><ol><li>Покажи калкулатора на екрана.</li><li>Задръж клавиша с логото на <strong>Windows</strong>, натисни <strong>Print Screen</strong> и отпусни клавишите. Надписът може да бъде <strong>Prt Scr</strong>, <strong>PrtSc</strong> или <strong>PrtScn</strong>.</li><li>Windows заснема целия екран и записва PNG файл в <strong>Картини → Екранни снимки (Pictures → Screenshots)</strong>.</li></ol><p>На някои клавиатури е необходимо да задържиш и <strong>Fn</strong>: <strong>Windows + Fn + PrtSc</strong>.</p><h3>Алтернатива през меню</h3><ol><li>Отвори <strong>Старт</strong>, напиши <strong>Изрязващ инструмент</strong> или <strong>Snipping Tool</strong> и избери приложението.</li><li>Избери режима за <strong>снимка</strong> с иконата на фотоапарат.</li><li>Отвори менюто за режим на заснемане и избери <strong>Цял екран (Full screen)</strong>.</li><li>Натисни <strong>Нов (New)</strong>. След заснемането снимката се отваря в инструмента.</li></ol><figure><img src="https://support.microsoft.com/en-us/windows/media/snipping-tool-opened-png.png" alt="Snipping Tool в Windows 11 с бутон New и меню за режим на снимане"><figcaption>Snipping Tool: бутонът New създава снимка с избрания режим. Изображение: Microsoft.</figcaption></figure><p>В следващата стъпка ще дадеш на файла <strong>описателно име</strong>.</p>'''),
    info('save-full', 'Запази снимката на целия екран с описателно име', '''<div class="key">Името на файла трябва да показва <strong>какво съдържа снимката и кой я е направил</strong>. Пример: <strong>screenshot-full-screen моето име.png</strong>.</div><h3>Ако използва Windows + Print Screen</h3><p>Алтернатива на тази комбинация е <strong>Старт → Snipping Tool → Цял екран → Нов</strong>, описана в предишната стъпка.</p><ol><li>Отвори <strong>Старт</strong>, напиши <strong>Файлов мениджър</strong> или <strong>File Explorer</strong> и избери приложението.</li><li>Вляво избери <strong>Картини (Pictures)</strong>, след това отвори <strong>Екранни снимки (Screenshots)</strong>. При архивиране към OneDrive папката „Картини“ може да е в OneDrive.</li><li>Намери най-новата снимка по датата и часа и я отвори с двойно щракване. Трябва да показва целия екран. Върни се в папката.</li><li>Щракни с десния бутон върху файла и избери <strong>Преименуване (Rename)</strong> — при някои изгледи това е икона в горния ред на менюто.</li><li>Замени името с <strong>screenshot-full-screen Martin</strong>, като използваш своето име. Ако се вижда разширението <strong>.png</strong>, запази го в края. Натисни <strong>Enter</strong>.</li></ol><h3>Ако използва менюто на Snipping Tool</h3><ol><li>В прозореца със заснетата снимка натисни бутона <strong>Запиши като (Save as)</strong> с икона на дискета.</li><li>Избери <strong>Картини (Pictures)</strong> и отвори <strong>Екранни снимки (Screenshots)</strong>. Ако такава папка още няма, натисни <strong>Нова папка (New folder)</strong>, дай ѝ това име и я отвори.</li><li>Въведи <strong>screenshot-full-screen Martin.png</strong> със своето име, избери формат <strong>PNG</strong> и натисни <strong>Запиши (Save)</strong>.</li></ol><div class="path">Картини → Екранни снимки → <strong>screenshot-full-screen Martin.png</strong></div><p>Снимката вече е готова за първото предаване. При нов опит добави към името например <strong>2</strong>, за да запазиш и предишния файл.</p>'''),
    submission('submit-full', 'Предай снимката на целия екран', 'screenshot-full-screen Martin.png', 'Картини → Екранни снимки', 'своята снимка на целия екран, на която се вижда прозорецът на калкулатора'),
    info('capture-area', 'Снимай само част от екрана', keys('Windows', 'Shift', 'S') + '''<p>Сега заснеми <strong>само областта около калкулатора</strong>. Това ще е второ, отделно изображение.</p><h3>С клавишна комбинация</h3><ol><li>Покажи калкулатора.</li><li>Задръж <strong>Windows</strong> и <strong>Shift</strong>, натисни <strong>S</strong> и отпусни клавишите.</li><li>В появилата се лента избери режима за <strong>снимка</strong> и <strong>правоъгълна област (Rectangle)</strong>.</li><li>Постави показалеца в горния ляв ъгъл на калкулатора. Задръж левия бутон на мишката, издърпай до долния десен ъгъл и отпусни.</li></ol><h3>Алтернатива през меню</h3><ol><li>Отвори <strong>Старт → Изрязващ инструмент (Snipping Tool)</strong>.</li><li>Избери режима за снимка, отвори менюто за режим и избери <strong>Правоъгълник (Rectangle)</strong>.</li><li>Натисни <strong>Нов (New)</strong> и маркирай областта около калкулатора по същия начин.</li></ol><div class="screen"><div class="label">Избери само желаната област</div><div class="selection"><div class="calculator">12 345</div></div></div><p>Снимката е в <strong>клипборда</strong> — временно място в паметта, от което можеш да я поставиш в друга програма. За нов опит повтори един от двата начина.</p>'''),
    info('paste-paint', 'Постави избраната част в Paint', keys('Ctrl', 'V') + '''<ol><li>Отвори <strong>Старт</strong>, напиши <strong>Paint</strong> и избери приложението.</li><li>В новото празно изображение натисни <strong>Ctrl + V</strong>.</li></ol><h3>Алтернатива през бутоните на Paint</h3><p>Избери <strong>Постави (Paste)</strong> от лентата с инструменти. Ако бутонът отвори меню, избери <strong>Постави (Paste)</strong> от него.</p>''' + flow('Избрана област в клипборда', 'Paint', 'Постави') + '''<p>Областта с калкулатора ще се появи в Paint. Ако вече има друга рисунка, първо я запази, ако ти е нужна, и избери <strong>Файл → Нов (File → New)</strong>, преди да поставиш снимката.</p><div class="example">Ако изображението не се появи, заснеми областта отново по един от начините в предишната стъпка и повтори поставянето.</div><p>Между заснемането и поставянето избягвай да копираш друг текст или картинка — това може да замени съдържанието на клипборда.</p>'''),
    info('save-area', 'Запиши избраната част като отделен файл', keys('Ctrl', 'S') + '''<h3>С клавишна комбинация</h3><p>Когато снимката е в Paint, натисни <strong>Ctrl + S</strong>. При първото записване се отваря прозорец за име и място.</p><h3>Алтернатива през меню</h3><p>В Paint избери <strong>Файл → Запиши като → PNG изображение (File → Save as → PNG picture)</strong>.</p><h3>Избери папка и описателно име</h3><ol><li>В прозореца за записване избери <strong>Документи (Documents)</strong>.</li><li>Сега създай папка: натисни <strong>Нова папка (New folder)</strong>, напиши <strong>Екранни снимки</strong> и натисни <strong>Enter</strong>. Ако папката вече съществува, използвай нея.</li><li>Отвори папката <strong>Екранни снимки</strong>, ако още не си в нея.</li><li>В полето <strong>Име на файл (File name)</strong> напиши <strong>screenshot-calculator Martin.png</strong>, като замениш Martin със своето име.</li><li>Избери тип <strong>PNG</strong> и натисни <strong>Запиши (Save)</strong>.</li></ol><div class="path">Документи → Екранни снимки → <strong>screenshot-calculator Martin.png</strong></div><div class="key">Това е <strong>втори файл</strong> с различно описателно име. Първата снимка на целия екран остава запазена.</div><p>За да отвориш файла, избери <strong>Старт → Файлов мениджър (File Explorer)</strong>, намери папката и щракни двукратно върху изображението. Трябва да се вижда избраната област около калкулатора.</p>'''),
    submission('submit-area', 'Предай снимката на избраната част', 'screenshot-calculator Martin.png', 'Документи → Екранни снимки', 'втория файл — снимката само на избраната област около калкулатора'),
    info('print-screen-setting', 'Накрая: как работи клавишът Prt Scr', keys('Prt Scr') + '''<p>Намери клавиша <strong>Prt Scr</strong>. Върху него може да пише <strong>Print Screen</strong>, <strong>PrtSc</strong> или <strong>PrtScn</strong>. На някои клавиатури трябва да задържиш заедно с Prt Scr и бутона <strong>Fn</strong>.</p><p>Когато използваш Prt Scr без клавиша Windows, действието му зависи от настройката в Windows 11.</p><div class="key"><strong>При включена настройка</strong> за отваряне на заснемането Prt Scr показва избора на област. <strong>При изключена настройка</strong> копира целия екран в клипборда; след това можеш да го поставиш в Paint чрез бутона <strong>Постави (Paste)</strong>.</div><p>Настройката се намира в <strong>Старт → Настройки → Достъпност → Клавиатура (Start → Settings → Accessibility → Keyboard)</strong> — използване на Print Screen за отваряне на заснемането на екрана.</p><p>Същият инструмент може да се отвори и през <strong>Старт → Изрязващ инструмент (Snipping Tool)</strong>, след което избираш режим и натискаш <strong>Нов (New)</strong>.</p><p>Вече предаде <strong>два отделни файла</strong>: целия екран и избрана част. Натисни <strong>„Завърши мисията“</strong>, за да приключиш.</p>'''),
]

mission = {'mission_version': 4, 'mission_id': 'basic-skills-windows11-screenshot-20261123-01', 'mission_content': {'title': TITLE, 'category': 'Базови умения', 'description': 'Две последователни упражнения в Windows 11: цял екран, запис и предаване; избрана част, запис и предаване. Клавишни комбинации с алтернативи през менюта и заключително обяснение за Prt Scr.', 'content_format': 'html', 'steps': steps}, 'mission_rules': {'allow_back_navigation': True, 'show_progress_panel': True}}

if __name__ == '__main__':
    (ROOT / 'windows11-screenshot.mission.json').write_text(json.dumps(mission, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    print('Built', len(steps), 'steps: 8 information + 2 file submissions; Prt Scr explanation last')
